/bin/zsh -lc "git diff --check
node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
const kb=JSON.parse(readFileSync('server/kristy_perimeter_kb.json','utf8'));
const old=JSON.parse(execFileSync('git',['show','HEAD:server/kristy_perimeter_kb.json'],{maxBuffer:64<<20}));
const pinText=readFileSync('server/test/acceptance/twoLinePin.js','utf8');
const start=pinText.indexOf('export const TWO_LINE = ')+'export const TWO_LINE = '.length;
const pins=JSON.parse(pinText.slice(start,pinText.indexOf('\\n};',start)+2));
const expected=['cooking_oils','nut_butter_ingredients','plant_butter','label_cold_pressed_expeller','mayo','deli_salads','hummus','rotisserie_chicken'];
const changed=[];
for(const e of kb.entries){
 const b=old.entries.find(x=>x.id===e.id);
 const fields=Object.keys(e).filter(k=>JSON.stringify(e[k])"'!==JSON.stringify(b[k]));
 if(!fields.length)continue;
 changed.push(e.id);
 for(const field of fields)assert.deepEqual(pins[e.id][field],e[field],e.id+'"'.'+field);
 assert.deepEqual(e.sources.slice(0,b.sources.length),b.sources,e.id+' lost sources');
 const copy=Object.entries(e).filter(([k])=>"'!['"'sources','aliases','asked_as','id','category','evidence_tier'].includes(k));
 assert.doesNotMatch(JSON.stringify(copy),/—/);
 console.log(e.id+': '+fields.join(', '));
}
assert.deepEqual(changed.toSorted(),expected.toSorted());
console.log('Exactly eight cards changed; every changed field pinned; previous sources retained; no em-dash asides.');
JS"
